using Contoso.Orders;

namespace Contoso.Orders.Tests;

[TestClass]
public sealed class OrderServiceTests
{
    private readonly OrderService _sut;

    public OrderServiceTests()
    {
        _sut = new OrderService();
    }

    private static List<OrderItem> CreateItems(params (string name, decimal price, int qty)[] items) =>
        items.Select(i => new OrderItem { ProductName = i.name, Price = i.price, Quantity = i.qty }).ToList();

    // --- CreateOrder: happy path ---

    [TestMethod]
    public void CreateOrder_WithValidItems_ReturnsOrderWithCorrectCustomerId()
    {
        // Arrange
        var items = CreateItems(("Widget", 10m, 2));

        // Act
        var order = _sut.CreateOrder("cust-1", items);

        // Assert
        Assert.AreEqual("cust-1", order.CustomerId);
    }

    [TestMethod]
    public void CreateOrder_WithValidItems_ReturnsOrderWithNonEmptyId()
    {
        var items = CreateItems(("Widget", 10m, 1));

        var order = _sut.CreateOrder("cust-1", items);

        Assert.IsNotNull(order.Id);
        Assert.IsTrue(Guid.TryParse(order.Id, out _), "Order Id should be a valid GUID.");
    }

    [TestMethod]
    public void CreateOrder_WithSingleItem_CalculatesTotalCorrectly()
    {
        var items = CreateItems(("Widget", 25.50m, 3));

        var order = _sut.CreateOrder("cust-1", items);

        Assert.AreEqual(76.50m, order.Total);
    }

    [TestMethod]
    public void CreateOrder_WithMultipleItems_SumsTotalAcrossAllItems()
    {
        var items = CreateItems(("Widget", 10m, 2), ("Gadget", 5m, 4));

        var order = _sut.CreateOrder("cust-1", items);

        Assert.AreEqual(40m, order.Total); // (10*2) + (5*4)
    }

    [TestMethod]
    public void CreateOrder_SetsCreatedAtToRecentTimestamp()
    {
        var before = DateTime.UtcNow;
        var items = CreateItems(("Widget", 10m, 1));

        var order = _sut.CreateOrder("cust-1", items);

        var after = DateTime.UtcNow;
        Assert.IsTrue(order.CreatedAt >= before && order.CreatedAt <= after,
            $"CreatedAt {order.CreatedAt} should be between {before} and {after}.");
    }

    [TestMethod]
    public void CreateOrder_StoresItemsOnOrder()
    {
        var items = CreateItems(("Widget", 10m, 1), ("Gadget", 5m, 2));

        var order = _sut.CreateOrder("cust-1", items);

        Assert.HasCount(2, order.Items);
    }

    // --- CreateOrder: validation ---

    [TestMethod]
    public void CreateOrder_WithNullCustomerId_ThrowsArgumentNullException()
    {
        var items = CreateItems(("Widget", 10m, 1));

        var ex = Assert.ThrowsExactly<ArgumentNullException>(() => _sut.CreateOrder(null!, items));
        Assert.AreEqual("customerId", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_WithNullItems_ThrowsArgumentNullException()
    {
        var ex = Assert.ThrowsExactly<ArgumentNullException>(() => _sut.CreateOrder("cust-1", null!));
        Assert.AreEqual("items", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_WithEmptyItems_ThrowsInvalidOperationException()
    {
        var ex = Assert.ThrowsExactly<InvalidOperationException>(
            () => _sut.CreateOrder("cust-1", []));
        Assert.Contains("no items", ex.Message, StringComparison.OrdinalIgnoreCase);
    }

    // --- GetOrder ---

    [TestMethod]
    public void GetOrder_AfterCreation_ReturnsSameOrder()
    {
        var items = CreateItems(("Widget", 10m, 1));
        var created = _sut.CreateOrder("cust-1", items);

        var retrieved = _sut.GetOrder(created.Id);

        Assert.AreSame(created, retrieved);
    }

    [TestMethod]
    public void GetOrder_WithNonExistentId_ReturnsNull()
    {
        var result = _sut.GetOrder("does-not-exist");

        Assert.IsNull(result);
    }

    // --- GetOrdersByCustomer ---

    [TestMethod]
    public void GetOrdersByCustomer_WithNoOrders_ReturnsEmptyList()
    {
        var result = _sut.GetOrdersByCustomer("cust-unknown");

        Assert.IsEmpty(result);
    }

    [TestMethod]
    public void GetOrdersByCustomer_ReturnsOnlyMatchingOrders()
    {
        var items = CreateItems(("Widget", 10m, 1));
        var order1 = _sut.CreateOrder("cust-A", items);
        _sut.CreateOrder("cust-B", items);
        var order2 = _sut.CreateOrder("cust-A", items);

        var result = _sut.GetOrdersByCustomer("cust-A");

        Assert.HasCount(2, result);
        Assert.Contains(order1, result);
        Assert.Contains(order2, result);
    }

    [TestMethod]
    public void GetOrdersByCustomer_ReturnsSingleOrder_WhenOnlyOneExists()
    {
        var items = CreateItems(("Widget", 10m, 1));
        var created = _sut.CreateOrder("cust-solo", items);

        var result = _sut.GetOrdersByCustomer("cust-solo");

        var single = Assert.ContainsSingle(result);
        Assert.AreSame(created, single);
    }
}

